# Generated by clients/macos/ci/release.sh in the switchback repository.
class Switchbak < Formula
  desc "Carry AI coding agent sessions to Switchbak"
  homepage "https://switchbak.dev"
  url "https://github.com/switchbackai/homebrew-tap/releases/download/v0.1.26/switchbak-0.1.26.zip"
  sha256 "6eb5dc4e423be08775a23d54cbfe5ed8489fde10528c2ba048bad94f252a42c6"

  depends_on arch: :arm64
  depends_on :macos

  # No `service do`: `switchbak login` enrols and then writes the launch
  # agents, with the host and the endpoint that `brew services` does not know.
  def install
    bin.install "bin/switchbak"
    share.install "share/switchbak"
  end

  def caveats
    <<~EOS
      To start sending this Mac's AI coding sessions to Switchbak:
        switchbak login
      (It signs you in with GitHub in your browser, then sets up the launch
      agents. `switchbak status` shows when your first session lands.)
      Before `brew uninstall switchbak`, run:
        switchbak teardown
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/switchbak version")
  end
end
